/* CastChknMapper.insertUserChknIslandList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_ISL ( SMLT_ID, TMNL_ID, CHKN_ISL_CD, BOOTH_CNT, KOS_CNT, SBD_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{island.island}, #{island.boothCnt}, #{island.kioskCnt}, #{island.bagDropCnt}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
