/* CastChknMapper.insertUserChknOperHrList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR ( SMLT_ID, TMNL_ID, CHKN_ISL_CD, OPER_HR_SN, OPER_BGNG_HR, OPER_END_HR, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{island.island}, #{oprTimeIdx} + 1, #{oprTime.bgnHour}, #{oprTime.endHour}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
