/* CastChknMapper.insertUserChknBoothList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH ( SMLT_ID, TMNL_ID, CHKN_ISL_CD, BOOTH_NO, ALN_CD, CSTM_ALCTN_YN, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{island.island}, #{booth.boothNo}, #{booth.alnCd}, #{booth.customYn}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
